def run_scalar_loop(records, sources, variables, frequency, router):
    origin = variables['origin']
    w = variables['frequency']
    chart = {'records': records}
    oldsrc = {'records': sources}
    actual = {}
    mapping = {}
    joins = []
    for (key, record) in chart['records'].items():
        old = oldsrc['records'][key]
        original = old['original']
        value = router.bind(key, record, old, w, frequency, origin)
        f.require(not value.has(w, *origin), 'complete physical frequency/background binding')
        if original in mapping:
            f.require(mapping[original] == value, 'identical source expression has identical analytic binding')
        mapping[original] = value
        actual[tuple(record['address'])] = value
        joins.append({'key': key, 'address': record['address'], 'original': original, 'analytic': record['analytic'], 'bound': value, 'unit': record['unit'], 'limits': record['limits']})
    return {'actual': actual, 'mapping': mapping, 'joins': joins}
